export const ROLES=[{id:'lead',name:'Tech Lead / Manager',short:'TL',rate:795},{id:'senior',name:'Senior Dev',short:'Senior Dev',rate:530},{id:'dev',name:'Développeur',short:'Dev',rate:475},{id:'qa',name:'QA',short:'QA',rate:445},{id:'arch',name:'Architecte',short:'Archi',rate:840}];
export const ACTORS={laurent:'Laurent',jennifer:'Jennifer',lassaad:'Lassaad'};
export const moneyRound=n=>Math.round((n+Number.EPSILON)*100)/100;
export const sum=xs=>moneyRound(xs.reduce((a,b)=>a+b,0));
export const uid=prefix=>`${prefix}-${crypto.randomUUID()}`;
const clone=x=>JSON.parse(JSON.stringify(x));
function assert(ok,message){if(!ok)throw Error(message);}
function actor(who,allowed){assert(allowed.includes(who),'Action non disponible pour ce profil');}
function finite(n){return typeof n==='number'&&Number.isFinite(n);}
export function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(Date.parse(s+'T12:00:00Z'))&&new Date(s+'T12:00:00Z').toISOString().slice(0,10)===s;}
export function validMonth(s){return typeof s==='string'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(s);}
export const monthStart=m=>m+'-01';
export function monthEnd(m){if(!validMonth(m))return '';const [y,n]=m.split('-').map(Number);return new Date(Date.UTC(y,n,0,12)).toISOString().slice(0,10);}
export function monthsBetween(a,b){if(!validDate(a)||!validDate(b)||a>b)return [];let m=a.slice(0,7),end=b.slice(0,7),out=[];while(m<=end&&out.length<240){out.push(m);const [y,n]=m.split('-').map(Number);m=new Date(Date.UTC(y,n,1,12)).toISOString().slice(0,7);}return out;}
export function weekdays(a,b){if(!validDate(a)||!validDate(b)||a>b)return 0;let n=0;for(let t=Date.parse(a+'T12:00:00Z'),end=Date.parse(b+'T12:00:00Z');t<=end;t+=86400000){const d=new Date(t).getUTCDay();if(d!==0&&d!==6)n++;}return n;}
export function daysInProjectMonth(p,m,monthlyDays){if(!validMonth(m)||!validDate(p.start)||!validDate(p.end)||p.start>p.end)return 0;const a=p.start>monthStart(m)?p.start:monthStart(m),b=p.end<monthEnd(m)?p.end:monthEnd(m);return weekdays(a,b)/weekdays(monthStart(m),monthEnd(m))*monthlyDays;}
export function staffingText(device){const f=new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1});return ROLES.filter(r=>device[r.id]>0).map(r=>`${f.format(device[r.id])} ${r.short}`).join(', ')||'À renseigner';}
export const dailyCost=(c,p)=>sum(ROLES.map(r=>(p.device[r.id]||0)*(c.rates[r.id]||0)));
export const plannedMonth=(c,p,m)=>moneyRound(daysInProjectMonth(p,m,c.monthlyDays)*dailyCost(c,p));
export function newProject(year=2027,overrides={}){return {id:uid('project'),name:'',category:'Build',budget:0,start:'',end:'',device:Object.fromEntries(ROLES.map(r=>[r.id,0])),openingValidated:0,pointsPlanned:null,pointsDelivered:null,epics:'',notes:'',...overrides};}
export function newCockpit(year=2027){return {id:uid('cockpit'),name:'',poRef:'',year,budget:0,start:`${year}-01-01`,end:`${year}-12-31`,reportMonth:`${year}-01`,openingMonth:'',owner:'Laurent',coOwner:'Jennifer',supplier:'Lassaad',monthlyDays:20,rates:Object.fromEntries(ROLES.map(r=>[r.id,r.rate])),projects:[newProject(year)],status:'draft',expenses:{},invoices:[],audit:[],demo:false};}
export function demoCockpit(){const c=newCockpit();Object.assign(c,{name:'Max / WeMax · Exemple',poRef:'124177',budget:1600000,demo:true});const specs=[['Max V2',550000,'2027-01-01','2027-06-30',{lead:.5,dev:3,qa:1}],['HYG',250000,'2027-02-01','2027-05-31',{lead:.5,dev:1,qa:.5}],['Hospitality Tech',300000,'2027-04-01','2027-06-30',{lead:.5,senior:1,qa:.5}],['Franchise',500000,'2027-01-01','2027-09-30',{lead:.5,dev:2,qa:1}]];c.projects=specs.map(([name,budget,start,end,device])=>newProject(c.year,{name,budget,start,end,device:{...Object.fromEntries(ROLES.map(r=>[r.id,0])),...device},notes:'Hypothèse de démonstration à confirmer, pas une date arrêtée en réunion.'}));return c;}
export function initialStore(){const c=demoCockpit();return {schema:3,activeId:c.id,cockpits:[c]};}
export function record(c,who,action){c.audit.unshift({who:ACTORS[who]||who,action,at:new Date().toISOString()});}
export function definitionIssues(c){const e=[];if(!c.name.trim())e.push('Nom du portefeuille obligatoire');if(!c.poRef.trim())e.push('Référence du PO obligatoire');if(!Number.isInteger(c.year)||c.year<2000||c.year>2100)e.push('Exercice entre 2000 et 2100 requis');if(!finite(c.budget)||c.budget<=0)e.push('Budget du PO positif requis');if(!validDate(c.start)||!validDate(c.end)||c.start>c.end)e.push('Période du PO invalide');else if(c.start.slice(0,4)!==String(c.year)||c.end.slice(0,4)!==String(c.year))e.push('La période du PO doit appartenir à son exercice');if(!validMonth(c.reportMonth)||c.reportMonth< c.start.slice(0,7)||c.reportMonth>c.end.slice(0,7))e.push('Arrêté mensuel hors de la période du PO');if(!c.owner.trim()||!c.coOwner.trim()||!c.supplier.trim())e.push('Responsables Accor et fournisseur obligatoires');if(!finite(c.monthlyDays)||c.monthlyDays<=0||c.monthlyDays>31)e.push('Capacité mensuelle entre 0 exclu et 31 jours requise');if(c.openingMonth&&(!validMonth(c.openingMonth)||c.openingMonth>c.reportMonth||c.openingMonth<c.start.slice(0,7)))e.push('Mois de reprise invalide');if(!c.projects.length)e.push('Au moins un projet requis');const ids=new Set(),epics=new Set();for(const p of c.projects){const label=p.name||'Projet sans nom';if(ids.has(p.id))e.push('Identifiant projet dupliqué');ids.add(p.id);if(!p.name.trim())e.push('Nom de chaque projet obligatoire');if(!['Build','Run','Hypercare'].includes(p.category))e.push(`${label} : type invalide`);if(!finite(p.budget)||p.budget<=0)e.push(`${label} : budget positif requis`);if(!validDate(p.start)||!validDate(p.end)||p.start>p.end)e.push(`${label} : dates de début et de fin obligatoires et cohérentes`);else if(p.start<c.start||p.end>c.end)e.push(`${label} : dates hors période du PO`);if(!finite(p.openingValidated)||p.openingValidated<0)e.push(`${label} : reprise du consommé invalide`);if(p.openingValidated>0&&!c.openingMonth)e.push('Un mois de reprise est requis pour le consommé initial');for(const field of ['pointsPlanned','pointsDelivered'])if(p[field]!==null&&(!finite(p[field])||p[field]<0))e.push(`${label} : story points invalides`);let capacity=0;for(const r of ROLES){const q=p.device[r.id];if(!finite(q)||q<0||q*2!==Math.round(q*2))e.push(`${label} : dispositif par pas de 0,5 requis`);else capacity+=q;if(!finite(c.rates[r.id])||c.rates[r.id]<0||q>0&&c.rates[r.id]<=0)e.push(`${r.short} : TJM positif requis pour un profil utilisé`);}if(!capacity)e.push(`${label} : dispositif à renseigner`);for(const key of p.epics.split(/[\s,;]+/).map(x=>x.trim().toUpperCase()).filter(Boolean)){if(epics.has(key))e.push(`Epic ${key} affectée à plusieurs projets`);epics.add(key);}}
 if(c.projects.every(p=>finite(p.budget))&&Math.abs(sum(c.projects.map(p=>p.budget))-c.budget)>.005)e.push('La somme des budgets projets doit égaler le budget du PO');return [...new Set(e)];}
function numericalIssues(c){const nums=[c.budget,c.monthlyDays,...Object.values(c.rates),...c.projects.flatMap(p=>[p.budget,p.openingValidated,...Object.values(p.device),...[p.pointsPlanned,p.pointsDelivered].filter(v=>v!==null)])];return nums.some(v=>!finite(v)||v<0);}
export function saveDefinition(c,input,who,activate=false){actor(who,['laurent','jennifer']);assert(!numericalIssues(input),'Les montants et capacités doivent être des nombres positifs ou nuls');const next={...c,...clone(input),id:c.id,expenses:c.expenses,invoices:c.invoices,audit:c.audit};for(const p of c.projects){if(!next.projects.some(q=>q.id===p.id)){const linked=Object.values(c.expenses).some(s=>s.rows.some(r=>r.projectId===p.id))||c.invoices.some(i=>i.lines.some(l=>l.projectId===p.id))||p.openingValidated>0;assert(!linked,'Un projet avec historique ne peut pas être supprimé ; ajustez sa date de fin');}}
 for(const m of Object.keys(c.expenses)){assert(m>=next.start.slice(0,7)&&m<=next.end.slice(0,7),'La période du PO ne peut pas exclure un mois déjà ventilé');assert(!next.openingMonth||m>next.openingMonth,'La reprise ne peut pas couvrir une ventilation existante');for(const row of c.expenses[m].rows){const p=next.projects.find(p=>p.id===row.projectId);if(p)assert(daysInProjectMonth(p,m,next.monthlyDays)>0,'Les dates projet ne peuvent pas exclure une ventilation existante');}}const issues=definitionIssues(next);if(activate||c.status==='active')assert(!issues.length,issues.join(' · '));next.status=activate||c.status==='active'?'active':'draft';Object.assign(c,next);record(c,who,activate?'Cockpit activé et hypothèses confirmées':'Paramétrage du cockpit enregistré');return c;}
export function getInvoiceForMonth(c,m){return c.invoices.findLast(i=>i.month===m&&i.status!=='cancelled');}
function expensePeriod(c,m){assert(c.status==='active','Le cockpit doit être activé par Laurent ou Jennifer');assert(validMonth(m)&&m>=c.start.slice(0,7)&&m<=c.end.slice(0,7),'Mois hors période du PO');assert(!c.openingMonth||m>c.openingMonth,'Ce mois est déjà couvert par la reprise du consommé');}
export function saveExpense(c,m,input,who,zeroConfirmed=false){actor(who,['lassaad']);expensePeriod(c,m);assert(!getInvoiceForMonth(c,m),'Une facture existe : reprenez la ventilation avant de la modifier');const seen=new Set(),rows=[];for(const x of input){assert(ROLES.some(r=>r.id===x.roleId),'Profil inconnu');assert(finite(x.days)&&x.days>=0&&Number.isSafeInteger(x.days*2),'Les jours doivent être positifs ou nuls, par pas de 0,5');if(!x.days)continue;assert(finite(c.rates[x.roleId])&&c.rates[x.roleId]>0,'TJM contractuel positif requis pour le profil ventilé');const p=c.projects.find(p=>p.id===x.projectId);assert(p||x.projectId===null,'Projet inconnu');assert(!p||daysInProjectMonth(p,m,c.monthlyDays)>0,`${p?.name} : imputation hors période projet`);assert(p||x.note?.trim(),'Une ligne non affectée doit être motivée');const key=(x.projectId||'unknown')+':'+x.roleId;assert(!seen.has(key),'Ligne projet/profil dupliquée');assert(Number.isFinite(x.days*c.rates[x.roleId]),'Valorisation trop grande');seen.add(key);rows.push({id:uid('expense'),projectId:x.projectId,projectName:p?.name||'Non affecté',roleId:x.roleId,days:x.days,rate:c.rates[x.roleId],amount:moneyRound(x.days*c.rates[x.roleId]),note:x.note?.trim()||''});}assert(rows.length||zeroConfirmed,'Confirmez explicitement un mois sans consommation');c.expenses[m]={month:m,rows,zeroConfirmed:!rows.length,savedAt:new Date().toISOString(),author:who};record(c,who,`Ventilation ${m} validée : ${sum(rows.map(r=>r.amount))} €`);return c.expenses[m];}
export function reviseExpense(c,m,reason,who){actor(who,['lassaad']);assert(reason.trim(),'Motif de révision requis');const i=getInvoiceForMonth(c,m);assert(!i||['draft','returned'].includes(i.status),'Une facture envoyée doit être retournée par l’owner du PO avant révision');if(i)i.status='cancelled';record(c,who,`Ventilation ${m} rouverte : ${reason.trim()}`);}
export function createInvoice(c,m,who){actor(who,['lassaad']);expensePeriod(c,m);const existing=getInvoiceForMonth(c,m);if(existing)return existing;const sheet=c.expenses[m];assert(sheet&&sheet.rows.length,'Enregistrez une ventilation non nulle avant de créer la facture');const i={id:uid('invoice'),number:`SIM-${c.poRef.replace(/[^a-zA-Z0-9-]/g,'')}-${m.replace('-','')}-${c.invoices.length+1}`,month:m,date:new Date().toISOString().slice(0,10),poRef:c.poRef,portfolioName:c.name,status:'draft',supplierNote:'',reviewNote:'',revision:1,lines:sheet.rows.map(r=>({id:r.id,projectId:r.projectId,projectName:r.projectName,roleId:r.roleId,expectedDays:r.days,expectedRate:r.rate,expectedAmount:r.amount,billedDays:r.days,billedRate:r.rate})),createdAt:new Date().toISOString()};c.invoices.push(i);record(c,who,`Facture ${i.number} créée`);return i;}
export function invoiceTotals(i){const expected=sum(i.lines.map(l=>l.expectedAmount)),billed=sum(i.lines.map(l=>moneyRound(l.billedDays*l.billedRate)));return {expected,billed,delta:moneyRound(billed-expected)};}
export function editInvoice(c,id,patch,who){actor(who,['lassaad']);const i=c.invoices.find(i=>i.id===id);assert(i&&['draft','returned'].includes(i.status),'Cette facture est verrouillée');const next={...clone(i),number:patch.number?.trim()||'',date:patch.date,supplierNote:patch.supplierNote?.trim()||''};assert(next.number,'Numéro de facture requis');assert(validDate(next.date),'Date de facture invalide');assert(!c.invoices.some(x=>x.id!==id&&x.number===next.number&&x.status!=='cancelled'),'Ce numéro de facture existe déjà');assert(patch.lines.length===i.lines.length&&new Set(patch.lines.map(l=>l.id)).size===patch.lines.length,'Les lignes de valorisation doivent être conservées sans doublon');for(const l of next.lines){const v=patch.lines.find(x=>x.id===l.id);assert(v&&finite(v.billedDays)&&v.billedDays>=0&&Number.isSafeInteger(v.billedDays*2),'Jours facturés invalides');assert(finite(v.billedRate)&&v.billedRate>=0,'TJM facturé invalide');assert(Number.isFinite(v.billedDays*v.billedRate),'Montant facturé trop grand');l.billedDays=v.billedDays;l.billedRate=moneyRound(v.billedRate);}next.status='draft';if(i.status==='returned')next.revision++;Object.assign(i,next);record(c,who,`Facture ${i.number} modifiée`);return i;}
export function sendInvoice(c,id,who){actor(who,['lassaad']);const i=c.invoices.find(i=>i.id===id);assert(i,'Facture inconnue');if(['sent','validated'].includes(i.status))return i;assert(i.status==='draft','Enregistrez la facture avant de l’envoyer');assert(i.lines.every(l=>l.projectId&&c.projects.some(p=>p.id===l.projectId)),'Affectez toutes les lignes à un projet avant envoi');assert(invoiceTotals(i).delta===0||i.supplierNote.trim(),'Expliquez l’écart de facturation avant envoi');i.status='sent';i.sentAt=new Date().toISOString();record(c,who,`Facture ${i.number} envoyée à l’owner du PO`);return i;}
export function isPoOwner(cockpit, who) {
  return ['laurent', 'jennifer'].includes(who) && cockpit.owner?.trim().toLowerCase() === who;
}
export function visiblePoInvoices(cockpit, who) {
  return cockpit.invoices.filter(invoice => who === 'lassaad' ||
    (isPoOwner(cockpit, who) && ['sent', 'returned', 'validated'].includes(invoice.status)));
}
export function pendingInvoiceDiscrepancies(cockpit, who) {
  return isPoOwner(cockpit, who)
    ? visiblePoInvoices(cockpit, who).filter(invoice => invoice.status === 'sent' && invoiceTotals(invoice).delta !== 0)
    : [];
}
export function validateInvoice(c,id,note,who){assert(isPoOwner(c,who),'Action réservée à l’owner du PO pour ce profil');const i=c.invoices.find(i=>i.id===id);assert(i,'Facture inconnue');if(i.status==='validated')return i;assert(i.status==='sent','La facture doit avoir été envoyée');assert(!invoiceTotals(i).delta||note.trim(),'Justification d’acceptation de l’écart requise');i.status='validated';i.reviewNote=note.trim();i.validatedAt=new Date().toISOString();record(c,who,`Facture ${i.number} validée : ${invoiceTotals(i).billed} €`);return i;}
export function returnInvoice(c,id,note,who){assert(isPoOwner(c,who),'Action réservée à l’owner du PO pour ce profil');const i=c.invoices.find(i=>i.id===id);assert(i?.status==='sent','Seule une facture à valider peut être retournée');assert(note.trim(),'Motif de retour requis');i.status='returned';i.reviewNote=note.trim();record(c,who,`Facture ${i.number} retournée : ${note.trim()}`);}
export function finances(c,asOf=c.reportMonth,scenario={}){const valid=validMonth(asOf),months=monthsBetween(c.start,c.end);const unknown=sum(Object.entries(c.expenses).flatMap(([m,s])=>(!c.openingMonth||m>c.openingMonth)?s.rows.filter(r=>r.projectId===null).map(r=>r.amount):[]));const issues=definitionIssues(c);let missing=new Set();const rows=c.projects.map(p=>{let actual=p.openingValidated||0,provisional=0,plannedPast=0,plannedFuture=0,committedFuture=0;const plannedTotal=sum(months.map(m=>plannedMonth(c,p,m)));for(const m of months){if(c.openingMonth&&m<=c.openingMonth)continue;const i=getInvoiceForMonth(c,m),sheet=c.expenses[m],past=valid&&m<=asOf;if(i?.status==='validated'){const amount=sum(i.lines.filter(l=>l.projectId===p.id).map(l=>moneyRound(l.amount ?? l.billedDays*l.billedRate)));if(past)actual+=amount;else committedFuture+=amount;}else if(sheet){const amount=sum(sheet.rows.filter(r=>r.projectId===p.id).map(r=>r.amount));if(past)provisional+=amount;else committedFuture+=amount;}else{const device=Object.hasOwn(scenario,p.id)?scenario[p.id]:null;const amount=plannedMonth(c,!past&&device?{...p,device}:p,m);if(past){plannedPast+=amount;if(amount>0)missing.add(m);}else plannedFuture+=amount;}}const forecast=issues.length?null:sum([actual,provisional,plannedPast,plannedFuture,committedFuture]);return {...p,actual:moneyRound(actual),provisional:moneyRound(provisional),plannedPast:moneyRound(plannedPast),plannedFuture:moneyRound(plannedFuture+committedFuture),forecast,remaining:moneyRound(p.budget-actual),plannedTotal,staffing:staffingText(p.device)};});const actual=sum(rows.map(p=>p.actual)),forecast=issues.length?null:sum(rows.map(p=>p.forecast))+unknown;return {rows,actual,remaining:moneyRound(c.budget-actual),forecast:forecast===null?null:moneyRound(forecast),budget:c.budget,plannedTotal:sum(rows.map(p=>p.plannedTotal)),provisional:sum(rows.map(p=>p.provisional)),unknown,unallocatedBudget:moneyRound(c.budget-sum(c.projects.map(p=>p.budget))),missingMonths:[...missing].sort(),issues};}
export function projectHealth(p,hasUnknown=false){if(p.actual>p.budget)return {color:'red',label:'Budget dépassé'};if(p.forecast===null||hasUnknown)return {color:'unknown',label:hasUnknown?'Ventilation à compléter':'À paramétrer'};const r=p.forecast/p.budget;return r>1?{color:'red',label:'Dépassement prévu'}:r>=.95?{color:'amber',label:'Sous surveillance'}:{color:'green',label:'Dans l’enveloppe'};}
export function validateStore(s){assert(s?.schema===3&&Array.isArray(s.cockpits)&&s.cockpits.length>0,'Sauvegarde incompatible');for(const c of s.cockpits){assert(Array.isArray(c.projects)&&Array.isArray(c.invoices)&&c.expenses&&Array.isArray(c.audit),'Données de cockpit incomplètes');assert(!numericalIssues(c),'Données numériques invalides');if(c.status==='active')assert(!definitionIssues(c).length,'Paramétrage actif invalide');}return s;}
